#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Created on Tue Jul 23 13:51:43 2024@author: ttaczak"""import numpy as npimport picklefrom scipy import interpolate as interpfrom pathlib import Pathdef get_temperature_profile_1D(self, x_axis = "rho", plot = False):    ### CXRS data for Ti ###        CXRS_data_loc = str(self.Ti_profile_path)    profile_time = 0.500        Ti_data_list = []    with (open(CXRS_data_loc, "rb")) as openfile:        while True:            try:                Ti_data_list.append(pickle.load(openfile))            except EOFError:                break        Ti_data_dict = Ti_data_list[0]    Ti_time = Ti_data_dict['time']    Ti_data = Ti_data_dict['Ti']    Ti_R = Ti_data_dict['R']        time_closest_index = np.argmin(np.abs(Ti_time - profile_time))    time_range = 20    Ti_smoothed = np.sum(Ti_data_dict['Ti'][time_closest_index-int(time_range/2):time_closest_index+int(time_range/2),:],axis = 0)/time_range        # Find the indices of the max value    j_psi_max, i_psi_max = np.unravel_index(np.argmax(self.psin), self.psin.shape)        # Get the corresponding (x, y) coordinates    R_psi_max = self.R[i_psi_max, j_psi_max]    Z_psi_max = self.Z[i_psi_max, j_psi_max]        Ti_x = (Ti_R - R_psi_max)/(np.max(self.LCFS[:,0]) - R_psi_max)    Ti_y = Ti_smoothed        Ti_spline = interp.splrep(Ti_x, Ti_y, k=1)        Ti_plotting_data = (Ti_x, Ti_y, Ti_time, Ti_data_dict, Ti_spline, time_closest_index)            return Ti_spline, Ti_plotting_data